                offset += grapheme.len();
            }
            if offset == self.cursor {
                if used >= room {
                    rows.push(String::new());
                    used = 0;
                }
                cursor = (rows.len() - 1, column(used));
            }
        }
        ComposerLayout { rows, cursor }
    }

